module parity_8bit (
    input [7:0] in,
    output out
);
    wire temp1, temp2, temp3, temp4;

    assign temp1 = in[0] ^ in[1];
    assign temp2 = in[2] ^ in[3];
    assign temp3 = in[4] ^ in[5];
    assign temp4 = in[6] ^ in[7];

    assign out = temp1 ^ temp2 ^ temp3 ^ temp4;
endmodule

