module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

wire [3:0] diff;
wire any_diff;

assign diff = a ^ b;
assign any_diff = diff[0] | diff[1] | diff[2] | diff[3];
assign equal = ~any_diff;

endmodule

