module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out = (in == 2'b00) ? 4'b0001 :
             (in == 2'b01) ? 4'b0010 :
             (in == 2'b10) ? 4'b0100 :
                              4'b1000;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out[0] = (~in[1]) & (~in[0]);
    assign out[1] = (~in[1]) & in[0];
    assign out[2] = in[1] & (~in[0]);
    assign out[3] = in[1] & in[0];
endmodule

