module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    reg [7:0] result;
    reg [15:0] in_abs;
    integer i;

    always @(*) begin
        // Handle negative input by taking absolute value
        if (in_0 < 0)
            in_abs = -in_0;
        else
            in_abs = in_0;

        result = 0;
        // Perform bitwise approximation of square root
        for (i = 7; i >= 0; i = i - 1) begin
            if ((result | (1 << i)) * (result | (1 << i)) <= in_abs)
                result = result | (1 << i);
        end

        out = result;
    end
endmodule

module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);

reg [7:0] result;
reg [15:0] abs_in;
reg [15:0] rem;
reg [7:0] bit;
integer i;

always @(*) begin
    // Handle negative input by taking absolute value
    if (in_0 < 0)
        abs_in = -in_0;
    else
        abs_in = in_0;

    result = 0;
    rem = 0;

    // Iterate over bits from the most significant to least significant
    for (i = 14; i >= 0; i = i - 1) begin
        // Shift rem left by 1 and bring down the next bit of abs_in
        rem = (rem << 1) | ((abs_in >> i) & 1);
        // Compute candidate
        bit = (result << 1) | 1;
        if (rem >= bit) begin
            rem = rem - bit;
            result = (result << 1) | 1;
        end else begin
            result = result << 1;
        end
    end
end

assign out = result;

endmodule

