module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

reg [7:0] x_reg1, x_reg2, x_reg3;
reg [15:0] sum1, sum2, sum3;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        x_reg1 <= 8'b0;
        x_reg2 <= 8'b0;
        x_reg3 <= 8'b0;
        sum1 <= 16'b0;
        sum2 <= 16'b0;
        sum3 <= 16'b0;
        y <= 16'b0;
    end else begin
        // Pipeline stage 1: register input
        x_reg1 <= x;
        // Pipeline stage 2: multiply by coefficient 1 (1)
        sum1 <= x_reg1;
        // Pipeline stage 3: register previous sum
        sum2 <= sum1;
        // Pipeline stage 4: multiply by coefficient 2 (2)
        sum3 <= sum2 << 1; // multiply by 2
        // Final stage: sum all
        y <= sum3 + sum2 + sum1;
    end
end

endmodule

