assign in_1_cu = in_1_sq * in_1;    // in_1^3
assign in_1_qu = in_1_cu * in_1;    // in_1^4
// in_1^5
wire signed [15:0] in_1_p5;
assign in_1_p5 = in_1_qu * in_1;    // in_1^5

// Compute cross terms
wire signed [15:0] in_0_in_1, in_0_sq_in_1, in_0_in_1_sq, in_0_cu_in_1;
assign in_0_in_1 = in_0 * in_1;             // in_0 * in_1
assign in_0_sq_in_1 = in_0_sq * in_1;       // in_0^2 * in_1
assign in_0_in_1_sq = in_0 * in_1_sq;       // in_0 * in_1^2
assign in_0_cu_in_1 = in_0_cu * in_1;       // in_0^3 * in_1

// Assign each term with appropriate scaling
// For simplicity, assume all multiplications are 8-bit * 8-bit -> 16-bit
// and that the coefficients are 1 (since not specified), so no scaling needed
