wire signed [31:0] scaled_in_0;
wire signed [31:0] scaled_in_1;
wire signed [31:0] scaled_in_2;

// Sum of inputs
assign sum_in = in_0 + in_1 + in_2;

// Scale each input by 0.1 (represented as 32-bit fixed point)
assign scaled_in_0 = (in_0 * 32'sd268435) >>> 28; // 0.1 in Q4.28 fixed point
assign scaled_in_1 = (in_1 * 32'sd268435) >>> 28;
