        result = {16'b0, P};
        // Calculate 1 + r/100 as fixed-point (scaled by 100)
        one_plus_r = (r + 8'd0) * 100 + 8'd0; // r in percentage, scaled by 100
        // For each year, multiply result by (1 + r/100)
        for (i = 0; i < n; i = i + 1) begin
