assign term7 = C7 * T_sq_R_sq;
assign term8 = C8; // constant term
assign term9 = C9 * T_R * R; // T*R*R

// Sum all terms
wire signed [31:0] sum_temp;
assign sum_temp = 
    { {16{term1[15]}}, term1 } +
    { {16{term2[15]}}, term2 } +
    { {16{term3[15]}}, term3 } +
    { {16{term4[15]}}, term4 } +
    { {16{term5[15]}}, term5 } +
    { {16{term6[15]}}, term6 } +
    { {16{term7[15]}}, term7 } +
    { {16{term8[15]}}, term8 } +
    { {16{term9[15]}}, term9 };

// Assign final output (truncate to 16 bits)
assign heat_index = sum_temp[15:0];

endmodule

module heat_index (
    input [7:0] temperature,
    input [7:0] humidity,
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,
    output signed [15:0] heat_index
);

    wire signed [15:0] T; // temperature as signed
    wire signed [15:0] R; // humidity as signed
    wire signed [15:0] T_sq; // T^2
    wire signed [15:0] R_sq; // R^2
    wire signed [15:0] T_R; // T*R
    wire signed [15:0] T_sq_R_sq; // T^2 * R^2

    // Convert inputs to signed
    assign T = { {8{temperature[7]}}, temperature };
    assign R = { {8{humidity[7]}}, humidity };

    // Compute T^2
    wire signed [31:0] T_mul_T;
    assign T_mul_T = T * T;
    // Take upper 16 bits for T^2
    assign T_sq = T_mul_T[15:0];

    // Compute R^2
    wire signed [31:0] R_mul_R;
    assign R_mul_R = R * R;
    assign R_sq = R_mul_R[15:0];

    // Compute T*R
    wire signed [31:0] T_mul_R;
    assign T_mul_R = T * R;
    assign T_R = T_mul_R[15:0];

    // Compute T^2 * R^2
    wire signed [63:0] T2_R2_mul;
    assign T2_R2_mul = T_sq * R_sq;
    assign T_sq_R_sq = T2_R2_mul[31:16]; // take the middle 16 bits for approximation

    // Compute heat_index
    wire signed [31:0] sum;
    assign sum = C1 + (C2 * T) + (C3 * R) + (C4 * T_sq) + (C5 * R_sq) + (C6 * T_R) + (C7 * T_sq_R_sq) + (C8 * T * R) + (C9 * T_sq_R_sq);
    assign heat_index = sum[15:0];

endmodule

module solar_radiation_average (
    input [7:0] r0, r1, r2, r3, r4, r5, r6, r7,
    output [7:0] avg_radiation
);

wire [9:0] sum;
wire [7:0] sum_divided;

// Sum all inputs
assign sum = r0 + r1 + r2 + r3 + r4 + r5 + r6 + r7;

// Divide sum by 8 to get average
// Since dividing by 8 is equivalent to shifting right by 3 bits
assign sum_divided = sum[9:3];

assign avg_radiation = sum_divided;

endmodule

